    { t: 2.0, p: { x: -1.15, y: 1.05, z: -0.85 }, v: { x: 0.65, y: 0.0, z: 0.0 }, a: { x: 0, y: 0, z: 0 } },
    { t: 4.1, p: { x: 0.15, y: 1.40, z: 0.25 }, v: { x: 0.65, y: 0.0, z: 0.0 }, a: { x: 0, y: 0, z: 0 } },
    { t: 6.1, p: { x: 1.35, y: 1.05, z: 1.05 }, v: { x: 0.60, y: 0.0, z: 0.0 }, a: { x: 0, y: 0, z: 0 } },
    { t: 8.0, p: { x: 2.05, y: 0.084, z: 1.65 }, v: { x: 0, y: 0, z: 0 }, a: { x: 0, y: 0, z: 0 } },
  ];
