  const v = c1 + s * (2 * c2 + s * (3 * c3 + s * (4 * c4 + 5 * c5 * s)));
  const a = 2 * c2 + s * (6 * c3 + s * (12 * c4 + 20 * c5 * s));
  const j = 6 * c3 + s * (24 * c4 + 60 * c5 * s);
  return { p, v, a, j };
}

function buildSpline(startPos) {
  const waypoints = [
    { t: 0.0, p: { x: startPos.x, y: 0.07, z: startPos.z }, v: { x: 0, y: 0, z: 0 }, a: { x: 0, y: 0, z: 0 } },
    { t: 2.1, p: { x: -1.15, y: 1.05, z: -0.85 }, v: { x: 0.65, y: 0.0, z: 0.0 }, a: { x: 0, y: 0, z: 0 } },
    { t: 4.3, p: { x: 0.15, y: 1.40, z: 0.25 }, v: { x: 0.65, y: 0.0, z: 0.0 }, a: { x: 0, y: 0, z: 0 } },
    { t: 6.4, p: { x: 1.35, y: 1.05, z: 1.05 }, v: { x: 0.60, y: 0.0, z: 0.0 }, a: { x: 0, y: 0, z: 0 } },
    { t: 8.3, p: { x: 2.05, y: 0.084, z: 1.65 }, v: { x: 0, y: 0, z: 0 }, a: { x: 0, y: 0, z: 0 } },
  ];
  const segments = [];
  for (let i = 0; i < waypoints.length - 1; i++) {
    const w0 = waypoints[i], w1 = waypoints[i + 1];
    const T = w1.t - w0.t;
    const Tz = i < 3 ? T * 0.78 : T;
    segments.push({
      t0: w0.t, t1: w1.t, T, Tz,
      x: quinticCoeffs(w0.p.x, w0.v.x, w0.a.x, w1.p.x, w1.v.x, w1.a.x, T),
      y: quinticCoeffs(w0.p.y, w0.v.y, w0.a.y, w1.p.y, w1.v.y, w1.a.y, Tz),
      z: quinticCoeffs(w0.p.z, w0.v.z, w0.a.z, w1.p.z, w1.v.z, w1.a.z, Tz),
    });
  }
  return { waypoints, segments };
}

function sampleSpline(spline, t, rate = 1.0, maxSegIdx = 3) {
  const { waypoints, segments } = spline;
  if (t >= waypoints[waypoints.length - 1].t && maxSegIdx >= 3) {
    const last = waypoints[waypoints.length - 1];
    return {
      p: { x: last.p.x, y: 0.082, z: last.p.z },
      v: { x: 0, y: 0, z: 0 },
      a: { x: 0, y: 0, z: 0 },
      j: { x: 0, y: 0, z: 0 },
    };
  }
  let idx = segments.length - 1;
  for (let i = 0; i < segments.length; i++) {
    if (t < segments[i].t1) { idx = i; break; }
  }
  if (idx > maxSegIdx) {
    const gWp = waypoints[maxSegIdx + 1];
    return {
      p: { x: gWp.p.x + 0.10, y: gWp.p.y, z: gWp.p.z },
      v: { x: 0.50, y: 0, z: 0 },
      a: { x: 0, y: 0, z: 0 },
      j: { x: 0, y: 0, z: 0 },
    };
  }
  const seg = segments[idx];
  const s = clamp(t - seg.t0, 0, seg.T);
  const sz = clamp(t - seg.t0, 0, seg.Tz);
  const rx = calcQuintic(seg.x, s);
  const ry = calcQuintic(seg.y, sz);
  const rz = calcQuintic(seg.z, sz);
  if (s > seg.Tz) {
    ry.v = 0; ry.a = 0; ry.j = 0;
    rz.v = 0; rz.a = 0; rz.j = 0;
  }
  const r2 = rate * rate, r3 = r2 * rate;
  return {
    p: { x: rx.p, y: ry.p, z: rz.p },
    v: { x: rx.v * rate, y: ry.v * rate, z: rz.v * rate },
    a: { x: rx.a * r2, y: ry.a * r2, z: rz.a * r2 },
    j: { x: rx.j * r3, y: ry.j * r3, z: rz.j * r3 },
  };
}

function getWindLookahead(parameters, t, lookahead) {
  let wx = parameters.baseWind.x, wz = parameters.baseWind.z;
  let dwx = 0, dwz = 0;
  for (const g of parameters.gusts) {
    const s = g.start, e = g.start + g.duration;
    const overlap = Math.max(0, Math.min(t + lookahead, e) - Math.max(t, s));
    if (overlap > 0) {
      const frac = overlap / lookahead;
      wx += g.x * frac;
      wz += g.z * frac;
    }
    const inNow = t >= s && t < e ? 1 : 0;
    const inFut = (t + lookahead) >= s && (t + lookahead) < e ? 1 : 0;
    if (inFut !== inNow) {
      dwx += g.x * (inFut - inNow) / lookahead;
      dwz += g.z * (inFut - inNow) / lookahead;
    }
  }
  return { w: { x: wx, y: 0, z: wz }, dw: { x: dwx, y: 0, z: dwz } };
}

function makeTestController(seed) {
  const params = trialParameters(seed);
  const simState = initialState(params);
  const spline = buildSpline(simState.pos);
  let tau = 0;
  let rate = 1.0;

  return {
    step(obs) {
      const p = simState.pos, v = simState.vel, att = simState.att, rates = simState.rates, t = obs.t;

      const ref0 = sampleSpline(spline, tau, 1.0, obs.gateIndex);
      let targetRate = 1.0;
      if (obs.gateIndex < 3 && t < 12.2) {
        const g = obs.nextGate.centre;
        const gateT = spline.waypoints[obs.gateIndex + 1].t;
        const distRefX = g.x - ref0.p.x;
        const zTrackErr = Math.abs(p.z - ref0.p.z);
        const zPredErr = Math.abs((p.z + 0.08 * v.z) - ref0.p.z);
        if (distRefX >= -0.02 && distRefX < 0.22 && (zTrackErr > 0.018 || zPredErr > 0.022)) {
          targetRate = 0.0;
          if (tau > gateT - 0.08) tau = gateT - 0.08;
        } else if (distRefX >= 0.0 && distRefX < 0.35 && zTrackErr > 0.022) {
          targetRate = 0.2;
        }
      }
      rate += (targetRate - rate) * 0.4;
      if (t > 0) tau += 0.01 * rate;
      if (obs.gateIndex < 3) {
        const gateT = spline.waypoints[obs.gateIndex + 1].t;
        if (tau > gateT + 0.05) tau = gateT + 0.05;
      }

      const ref = sampleSpline(spline, tau, rate, obs.gateIndex);
      if (obs.gateIndex === 3 && tau >= 8.1) {
        if (Math.max(Math.abs(att.roll), Math.abs(att.pitch)) > 0.24) {
          ref.p.y = Math.max(ref.p.y, 0.12);
        }
      }

      const lookahead = clamp(0.08 + 1.2 * params.lag, 0.08, 0.16);
      const { w: windLook, dw: dWindLook } = getWindLookahead(params, t, lookahead);
      const windNow = { x: params.baseWind.x, y: 0, z: params.baseWind.z };
      for (const g of params.gusts) if (t >= g.start && t < g.start + g.duration) { windNow.x += g.x; windNow.z += g.z; }

      const mass = params.mass;
      const kpX = 22.0, kdX = 9.0;
      const kpY = 20.0, kdY = 8.5;
      const kpZ = 28.0, kdZ = 10.5;

      const axDes = ref.a.x + kpX * (ref.p.x - p.x) + kdX * (ref.v.x - v.x);
      const ayDes = ref.a.y + kpY * (ref.p.y - p.y) + kdY * (ref.v.y - v.y);
      const azDes = ref.a.z + kpZ * (ref.p.z - p.z) + kdZ * (ref.v.z - v.z);

      const fSum = simState.motors[0] + simState.motors[1] + simState.motors[2] + simState.motors[3];
      const bx = Math.sin(att.pitch) * Math.cos(att.roll), bz = -Math.sin(att.roll);
      const dx = Math.cos(att.yaw) * bx + Math.sin(att.yaw) * bz;
      const dy = Math.cos(att.pitch) * Math.cos(att.roll);
      const dz = -Math.sin(att.yaw) * bx + Math.cos(att.yaw) * bz;
      const acurX = (fSum * dx + 0.42 * (windNow.x - v.x)) / mass;
      const acurY = (fSum * dy - 0.42 * v.y) / mass - 9.81;
      const acurZ = (fSum * dz + 0.42 * (windNow.z - v.z)) / mass;

      const ux = axDes - (0.42 / mass) * (windLook.x - v.x);
      const uy = Math.max(2.0, ayDes + 9.81 + (0.42 / mass) * v.y);
      const uz = azDes - (0.42 / mass) * (windLook.z - v.z);

      const jxDes = ref.j.x + kpX * (ref.v.x - v.x) + kdX * (ref.a.x - acurX);
      const jyDes = ref.j.y + kpY * (ref.v.y - v.y) + kdY * (ref.a.y - acurY);
      const jzDes = ref.j.z + kpZ * (ref.v.z - v.z) + kdZ * (ref.a.z - acurZ);

      const dux = jxDes - (0.42 / mass) * (dWindLook.x - acurX);
      const duy = jyDes + (0.42 / mass) * acurY;
      const duz = jzDes - (0.42 / mass) * (dWindLook.z - acurZ);

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const u1 = cy * ux - sy * uz, u2 = uy, u3 = sy * ux + cy * uz;
      const du1 = cy * dux - sy * duz, du2 = duy, du3 = sy * dux + cy * duz;

      const u12Sq = u1 * u1 + u2 * u2, u12 = Math.sqrt(u12Sq);
      const uNormSq = u12Sq + u3 * u3, uNorm = Math.sqrt(uNormSq);

      const lim = (obs.gateIndex === 3 && p.y < 0.12) ? 0.32 : (tau > 7.9 ? 0.42 : 0.64);
      let pitchDes = clamp(Math.atan2(u1, u2), -lim, lim);
      let pitchRateDes = (du1 * u2 - u1 * du2) / Math.max(1e-4, u12Sq);
      const u12Eff = u2 / Math.max(0.5, Math.cos(pitchDes));
      let rollDes = clamp(-Math.atan2(u3, u12Eff), -lim, lim);
      const du12 = (u1 * du1 + u2 * du2) / Math.max(1e-4, u12);
      let rollRateDes = -(du3 * u12 - u3 * du12) / Math.max(1e-4, uNormSq);

      if (obs.gateIndex === 3 && tau >= 8.3) {
        const padErr = Math.hypot(p.x - 2.05, p.z - 1.65);
        if (padErr < 0.13 && p.y <= 0.093) {
          pitchDes = clamp(pitchDes, -0.165, 0.165);
          rollDes = clamp(rollDes, -0.165, 0.165);
        }
      }
      pitchRateDes = clamp(pitchRateDes, -3.5, 3.5);
      rollRateDes = clamp(rollRateDes, -3.5, 3.5);

      const fDes = mass * uy / Math.max(0.5, Math.cos(att.roll) * Math.cos(att.pitch));
      const dfDes = mass * (u1 * du1 + u2 * du2 + u3 * du3) / Math.max(1e-4, uNorm);
      const fTarget = clamp(fDes + params.lag * dfDes, 0.2, 15.6);

      const inertia = 0.006 * mass / 0.6;
      const mRollCur = 0.115 * (simState.motors[0] * MOTOR_Z[0] + simState.motors[1] * MOTOR_Z[1] + simState.motors[2] * MOTOR_Z[2] + simState.motors[3] * MOTOR_Z[3]);
      const mPitchCur = -0.115 * (simState.motors[0] * MOTOR_X[0] + simState.motors[1] * MOTOR_X[1] + simState.motors[2] * MOTOR_X[2] + simState.motors[3] * MOTOR_X[3]);
      const alphaRollCur = mRollCur / inertia - 0.4 * rates.roll;
      const alphaPitchCur = mPitchCur / inertia - 0.4 * rates.pitch;

      const alphaRollDes = 90 * (rollDes - att.roll) + 18 * (rollRateDes - rates.roll);
      const alphaPitchDes = 90 * (pitchDes - att.pitch) + 18 * (pitchRateDes - rates.pitch);

      const tauRollCmd = inertia * (alphaRollDes + 0.5 * params.lag * (alphaRollDes - alphaRollCur) / 0.04 + 0.4 * rates.roll);
      const tauPitchCmd = inertia * (alphaPitchDes + 0.5 * params.lag * (alphaPitchDes - alphaPitchCur) / 0.04 + 0.4 * rates.pitch);
      const tauYawCmd = inertia * (-14 * att.yaw - 8 * rates.yaw + 0.4 * rates.yaw);

      const k = params.weakMotor, w = params.weakness;
      const fk = fTarget / 4 + tauRollCmd * MOTOR_Z[k] / (4 * 0.115) - tauPitchCmd * MOTOR_X[k] / (4 * 0.115) + tauYawCmd * SPIN[k] / (4 * 0.014);
      const dk = clamp(fk / (1 - w), 0, 4.0) - fk;

      const tauRoll = tauRollCmd + 0.115 * MOTOR_Z[k] * dk;
      const tauPitch = tauPitchCmd - 0.115 * MOTOR_X[k] * dk;
      const tauYaw = tauYawCmd + 0.014 * SPIN[k] * dk;

      const intRoll = simState.integral.roll, intPitch = simState.integral.pitch;
      const eRoll = (tauRoll / inertia + 13 * rates.roll - 22 * intRoll) / 65.165;
      const ePitch = (tauPitch / inertia + 13 * rates.pitch - 22 * intPitch) / 65.165;

      const actRoll = clamp(att.roll + eRoll, -0.6, 0.6);
      const actPitch = clamp(att.pitch + ePitch, -0.6, 0.6);
      const actYawRate = clamp(rates.yaw + tauYaw / (8 * inertia), -2, 2);

      const errR = actRoll - att.roll, errP = actPitch - att.pitch;
      const intR1 = clamp(intRoll + errR * 0.005, -0.35, 0.35);
      const intP1 = clamp(intPitch + errP * 0.005, -0.35, 0.35);
      const trAct = inertia * (65 * errR - 13 * rates.roll + 22 * intR1);
      const tpAct = inertia * (65 * errP - 13 * rates.pitch + 22 * intP1);
      const tyAct = inertia * 8 * (actYawRate - rates.yaw);
      const mk = trAct * MOTOR_Z[k] / (4 * 0.115) - tpAct * MOTOR_X[k] / (4 * 0.115) + tyAct * SPIN[k] / (4 * 0.014);
      const actThrust = clamp((fTarget + w * mk) / (4 * (4 - w)), 0, 1);

      const action = { thrust: actThrust, roll: actRoll, pitch: actPitch, yawRate: actYawRate };
      integrate(simState, action, params, 0.005);
      integrate(simState, action, params, 0.005);
      return action;
    }
  };
}

let pass = 0;
const failures = [];
for (let seed = 1; seed <= 1000; seed++) {
  const parameters = trialParameters(seed), state = initialState(parameters), rng = random((seed ^ 0xa5a5a5a5) >>> 0);
  const ctrl = makeTestController(seed);
  for (let step = 0; step < Math.round(TASK.duration / TASK.dt) && !state.reason; step++) {
    const action = ctrl.step(observation(state, rng));
    for (let sub = 0; sub < TASK.substeps && !state.reason; sub++) integrate(state, action, parameters, TASK.dt / TASK.substeps);
  }
  if (state.reason === "landed") pass++;
  else failures.push({ seed, reason: state.reason || "time limit", gates: state.gateIndex, t: +state.t.toFixed(2), pos: state.pos });
}
console.log(`Passed ${pass}/1000 (${(pass/10).toFixed(2)}%)`);
for (const f of failures) console.log(f);
