import { trialParameters, random, TASK, GATES, PAD } from './tasks/drone-hard/task.mjs';
import { initialState } from './tasks/drone-hard/sim.mjs';

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const norm = (v) => Math.hypot(v.x, v.y, v.z);
const copy = (v) => ({ ...v });
const MOTOR_X = [-1, 1, 1, -1], MOTOR_Z = [-1, -1, 1, 1], SPIN = [1, -1, 1, -1];

function quinticCoeffs(p0, v0, a0, p1, v1, a1, T) {
  const c0 = p0, c1 = v0, c2 = 0.5 * a0;
