  const rx = calcQuintic(seg.x, s), ry = calcQuintic(seg.y, s), rz = calcQuintic(seg.z, s);
  return { p: { x: rx.p, y: ry.p, z: rz.p }, v: { x: rx.v, y: ry.v, z: rz.v }, a: { x: rx.a, y: ry.a, z: rz.a }, j: { x: rx.j, y: ry.j, z: rz.j } };
